import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class AK375 {
    public static Scanner input = new Scanner(System.in);
    public String processString(int length, String inputStr) {
        StringBuilder segmentBuffer = new StringBuilder();
        StringBuilder mainBuffer = new StringBuilder();
        int maxSegmentLength = 0;
        int segmentCount = 0;

        for (int index = 0; index < length; index++) {
            char ch = inputStr.charAt(index);
            if (ch == '(') {
                segmentBuffer.append('_');
                int nextIdx = index + 1;
                while (nextIdx < length && inputStr.charAt(nextIdx) != ')') {
                    segmentBuffer.append(inputStr.charAt(nextIdx));
                    nextIdx++;
                }
                index = nextIdx; // move index to position after ')'
            } else if (ch == ')') {
                mainBuffer.append('_');
            } else {
                mainBuffer.append(ch);
            }
        }

        String[] segments = segmentBuffer.toString().split("_");
        List<String> segmentList = new ArrayList<>();
        for (String s : segments) {
            if (s != null && !s.isEmpty()) {
                segmentList.add(s);
            }
        }
        segmentCount = segmentList.size();

        String[] mainParts = mainBuffer.toString().split("_");
        for (String part : mainParts) {
            if (part.length() > maxSegmentLength) {
                maxSegmentLength = part.length();
            }
        }
        return maxSegmentLength + " " + segmentCount;
    }

    public static void main(String[] args) {
        while (input.hasNext()) {
            int n = input.nextInt();
            String s = input.next();
            long start = System.currentTimeMillis();
            String output = new AK375().processString(n, s);
            long end = System.currentTimeMillis();
            System.out.println(output);
        }
    }
}
