#include <iostream>
#include <vector>
#include <string>
#include <sstream>

class AK375 {
public:
    std::string processString(int length, const std::string& inputStr) {
        std::stringstream segmentBuffer;
        std::stringstream mainBuffer;
        int maxSegmentLength = 0;
        int segmentCount = 0;

        for (int index = 0; index < length; index++) {
            char ch = inputStr[index];
            if (ch == '(') {
                segmentBuffer << '_';
                int nextIdx = index + 1;
                while (nextIdx < length && inputStr[nextIdx] != ')') {
                    segmentBuffer << inputStr[nextIdx];
                    nextIdx++;
                }
                index = nextIdx; // move index to position after ')'
            } else if (ch == ')') {
                mainBuffer << '_';
            } else {
                mainBuffer << ch;
            }
        }

        std::string segmentStr = segmentBuffer.str();
        std::vector<std::string> segments;
        std::stringstream ss(segmentStr);
        std::string token;
        while (std::getline(ss, token, '_')) {
            if (!token.empty()) {
                segments.push_back(token);
            }
        }
        segmentCount = segments.size();

        std::string mainStr = mainBuffer.str();
        std::stringstream mainSS(mainStr);
        std::string part;
        while (std::getline(mainSS, part, '_')) {
            if ((int)part.length() > maxSegmentLength) {
                maxSegmentLength = part.length();
            }
        }
        return std::to_string(maxSegmentLength) + " " + std::to_string(segmentCount);
    }
};

int main() {
    AK375 processor;
    int n;
    while (std::cin >> n) {
        std::string s;
        std::cin >> s;
        std::cout << processor.processString(n, s) << std::endl;
    }
    return 0;
}

